import pandas as pd

# Path to the raw eBird CSV generated by the retrieval script
csv_path = r'd:/gdrive/models/hpai-heterogeneous-gnn-canada/data/raw/ebird_api/ebird_observations_raw_2026.csv'

df = pd.read_csv(csv_path)

print('--- eBird API Raw Data Summary ---')
print(f'Total rows (observations): {len(df)}')
print('Columns:')
for col in df.columns:
    print(f'  - {col}')
print('\nFirst 5 rows:')
print(df.head().to_string(index=False))

# Show distinct species codes (waterfowl focus)
if 'species_code' in df.columns:
    distinct_species = df['species_code'].nunique()
    print(f'\nDistinct species codes: {distinct_species}')
    # Show top 10 most frequent species codes
    top_species = df['species_code'].value_counts().head(10)
    print('Top 10 species codes by observation count:')
    print(top_species.to_string())

# Show distribution by province/region (if present)
if 'region' in df.columns:
    region_counts = df['region'].value_counts().head(10)
    print('\nObservations per eBird region (top 10):')
    print(region_counts.to_string())

# Show date range of observations
if 'observation_date' in df.columns:
    df['observation_date'] = pd.to_datetime(df['observation_date'], errors='coerce')
    min_date = df['observation_date'].min()
    max_date = df['observation_date'].max()
    print(f'\nObservation date range: {min_date.date()} to {max_date.date()}')
